<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --navy: #0d1b2a;
    --blue-dark: #1a3a5c;
    --blue-mid: #1e6091;
    --blue-light: #2980b9;
    --teal: #1abc9c;
    --amber: #e67e22;
    --red: #c0392b;
    --green: #27ae60;
    --purple: #8e44ad;
    --gray-100: #f5f7fa;
    --gray-200: #e8ecf0;
    --gray-400: #9aaab4;
    --gray-700: #3d4f5c;
    --gray-900: #1a252f;
    --white: #ffffff;
    --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: var(--font);
    background: var(--gray-100);
    color: var(--gray-900);
    line-height: 1.6;
    font-size: 14px;
  }
  /* HEADER */
  .report-header {
    background: linear-gradient(135deg, var(--navy) 0%, var(--blue-dark) 60%, var(--blue-mid) 100%);
    color: var(--white);
    padding: 48px 60px 40px;
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute; top: 0; right: 0; bottom: 0;
    width: 40%;
    background: url("data:image/svg+xml,%3Csvg width='600' height='300' viewBox='0 0 600 300' xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='500' cy='50' r='200' fill='rgba(255,255,255,0.03)'/%3E%3Ccircle cx='400' cy='200' r='150' fill='rgba(255,255,255,0.03)'/%3E%3C/svg%3E") no-repeat center;
    background-size: cover;
  }
  .header-tag {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--teal);
    margin-bottom: 12px;
  }
  .report-header h1 {
    font-size: 30px;
    font-weight: 700;
    line-height: 1.2;
    max-width: 700px;
    margin-bottom: 12px;
