  .header-meta {
    display: flex;
    gap: 32px;
    flex-wrap: wrap;
  }
  .header-meta-item {
    font-size: 12px;
    color: rgba(255,255,255,0.55);
  }
  .header-meta-item strong {
    color: rgba(255,255,255,0.88);
    display: block;
    font-size: 13px;
  }
  /* LAYOUT */
  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 32px 24px;
  }
  /* KPI STRIP */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 0;
    background: var(--white);
    border: 1px solid var(--gray-200);
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 32px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
  }
  .kpi-card {
    padding: 20px 18px;
    border-right: 1px solid var(--gray-200);
    position: relative;
  }
  .kpi-card:last-child { border-right: none; }
  .kpi-label {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: var(--gray-400);
    margin-bottom: 6px;
  }
  .kpi-value {
    font-size: 26px;
    font-weight: 700;
    color: var(--blue-dark);
    line-height: 1;
    margin-bottom: 4px;
  }
  .kpi-sub {
    font-size: 11.5px;
    color: var(--gray-400);
  }
  .kpi-badge {
    display: inline-block;
    font-size: 10px;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 20px;
    margin-top: 6px;
  }
  .badge-up { background: #fdecea; color: var(--red); }
  .badge-green { background: #e8f8f2; color: var(--green); }
  .badge-amber { background: #fef3e2; color: var(--amber); }
  /* SECTION */
  .section {
    background: var(--white);
    border: 1px solid var(--gray-200);
    border-radius: 10px;
    padding: 28px 32px;
    margin-bottom: 24px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.04);
  }
  .section-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    margin-bottom: 20px;
    padding-bottom: 14px;
    border-bottom: 2px solid var(--gray-200);
  }
  .section-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px; height: 28px;
    background: var(--blue-mid);
    color: var(--white);
    border-radius: 50%;
    font-size: 12px;
    font-weight: 700;
    margin-right: 12px;
    flex-shrink: 0;
    margin-top: 2px;
