    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
    margin-top: 20px;
  }
  .chart-wrap {
    background: var(--gray-100);
    border: 1px solid var(--gray-200);
    border-radius: 8px;
    padding: 16px;
  }
  .chart-wrap h3 {
    font-size: 13px;
    font-weight: 700;
    color: var(--gray-700);
    margin-bottom: 4px;
  }
  .chart-wrap p {
    font-size: 11.5px;
    color: var(--gray-400);
    margin-bottom: 12px;
  }
  .chart-wrap canvas { max-height: 260px; }
  .chart-full { grid-column: 1 / -1; }
  .chart-tall canvas { max-height: 340px !important; }
  /* DATA TABLE */
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin-top: 16px;
  }
  thead tr { background: var(--navy); color: var(--white); }
  thead th {
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 12px;
    letter-spacing: 0.3px;
  }
  tbody tr:nth-child(even) { background: var(--gray-100); }
  tbody tr:hover { background: #e3eaf0; }
  tbody td { padding: 9px 14px; border-bottom: 1px solid var(--gray-200); }
  .td-num { text-align: right; font-variant-numeric: tabular-nums; }
  /* INSIGHT BOX */
  .insight-box {
    background: linear-gradient(135deg, #eaf4fb 0%, #e8f8f2 100%);
    border-left: 4px solid var(--blue-mid);
