  }
  .finding-body p { font-size: 13px; color: var(--gray-700); }
  .tag {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 10.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-right: 6px;
    margin-bottom: 6px;
  }
  .tag-policy { background: #e8eaff; color: #3949ab; }
  .tag-risk { background: #fdecea; color: var(--red); }
  .tag-equity { background: #e8f8f2; color: var(--green); }
  /* CORRELATION CALLOUT */
  .corr-callout {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 16px;
    margin-top: 16px;
  }
  .corr-card {
    background: var(--white);
    border: 1px solid var(--gray-200);
    border-radius: 8px;
    padding: 16px;
    text-align: center;
  }
  .corr-value {
    font-size: 28px;
    font-weight: 700;
    color: var(--blue-mid);
    margin-bottom: 4px;
  }
  .corr-label { font-size: 12px; color: var(--gray-400); }
  /* FOOTER */
  .report-footer {
    background: var(--navy);
    color: rgba(255,255,255,0.5);
    text-align: center;
    padding: 24px;
    font-size: 12px;
    margin-top: 40px;
  }
  .report-footer strong { color: rgba(255,255,255,0.8); }
  /* RESPONSIVE */
  @media (max-width: 900px) {
    .kpi-strip { grid-template-columns: repeat(3, 1fr); }
    .chart-grid-2 { grid-template-columns: 1fr; }
    .chart-grid-3 { grid-template-columns: 1fr; }
    .corr-callout { grid-template-columns: 1fr; }
  }
  .color-dot {
    display: inline-block;
    width: 10px; height: 10px;
    border-radius: 50%;
    margin-right: 5px;
    vertical-align: middle;
  }
  .progress-bar-wrap { margin-top: 8px; }
  .progress-bar-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 7px;
    font-size: 12.5px;
  }
  .progress-label { width: 120px; text-align: right; color: var(--gray-700); flex-shrink: 0; }
  .progress-track {
    flex: 1;
    background: var(--gray-200);
    border-radius: 4px;
    height: 10px;
    overflow: hidden;
