  .progress-val { width: 50px; font-weight: 600; color: var(--gray-700); flex-shrink: 0; }
  /* NOTE */
  .data-note {
    font-size: 11.5px;
    color: var(--gray-400);
    font-style: italic;
    margin-top: 10px;
    padding: 8px 12px;
    background: #fffbf0;
    border-left: 3px solid var(--amber);
    border-radius: 4px;
  }
</style>
