    <div class="kpi-label">Brent–Retail Correlation</div>
    <div class="kpi-value">r = 0.26</div>
    <div class="kpi-sub">Petrol (cross-sectional)</div>
    <span class="kpi-badge badge-amber">Moderate pass-through</span>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Subsidy Dampening Effect</div>
    <div class="kpi-value">79.5%</div>
    <div class="kpi-sub">High vs. Low subsidy (petrol)</div>
    <span class="kpi-badge badge-green">Strong buffering</span>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Regional Price Spread</div>
    <div class="kpi-value">$2.87</div>
    <div class="kpi-sub">Max–min spread in 2026</div>
    <span class="kpi-badge badge-up">Up from $1.61 in 2020</span>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Avg. Tax-to-Price</div>
    <div class="kpi-value">26.8%</div>
    <div class="kpi-sub">Global average (all countries)</div>
    <span class="kpi-badge badge-amber">High: 34.7% · Low: 22.9%</span>
  </div>
</div>

<!-- ===== SECTION 1: GLOBAL OVERVIEW ===== -->
<div class="section">
  <div class="section-header">
    <div class="section-title-wrap">
      <div class="section-number">1</div>
      <div>
        <h2>Global Fuel Price Overview</h2>
        <div class="section-desc">Summary statistics for petrol, diesel, and LPG across the full 2020–2026 period with Brent Crude as baseline</div>
      </div>
    </div>
  </div>

  <div class="chart-grid-2">
    <div class="chart-wrap">
      <h3>Average Fuel Price by Type (USD/Liter)</h3>
      <p>Global mean across all 84 countries and 327 weekly observations</p>
      <canvas id="chartFuelTypeAvg"></canvas>
    </div>
    <div class="chart-wrap">
      <h3>Yearly Average Prices: All Fuel Types</h3>
